add_action('rest_api_init', function() {
  register_rest_route('fsurgery/v1', '/read', array(
    'methods' => 'GET',
    'permission_callback' => function() { return current_user_can('manage_options'); },
    'callback' => function($req) {
      $out = array();
      $pid = intval($req->get_param('post'));
      if ($pid) {
        $out['meta'] = array();
        foreach (get_post_meta($pid) as $k => $v) { $out['meta'][$k] = maybe_unserialize($v[0]); }
        $out['post'] = array('post_type' => get_post_type($pid), 'status' => get_post_status($pid));
      }
      $opt = get_option('xts-woodmart-options');
      if (is_array($opt)) {
        $out['xts_footer'] = array();
        foreach ($opt as $k => $v) { if (preg_match('/footer|prefooter|single_footer|page_footer/i', $k)) $out['xts_footer'][$k] = $v; }
      } else { $out['xts_type'] = gettype($opt); }
      $out['theme_mods_woodmart'] = get_option('theme_mods_woodmart');
      $out['sidebars'] = wp_get_sidebars_widgets();
      $out['widgets_opt'] = array();
      foreach (array('widget_woodmart-html-block', 'widget_block', 'widget_text') as $w) { $out['widgets_opt'][$w] = get_option($w); }
      return $out;
    }
  ));
});
